package br.com.mathinclui.professor.domain;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="professores") public class Professor { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=120) private String nome; @Column(nullable=false,unique=true,length=180) private String email; @Column(name="senha_hash",nullable=false) private String senhaHash; @Column(nullable=false) private boolean ativo=true; @Column(name="criado_em",nullable=false) private Instant criadoEm; @Column(name="atualizado_em",nullable=false) private Instant atualizadoEm; protected Professor(){} public Professor(String nome,String email,String senhaHash){this.nome=nome;this.email=email;this.senhaHash=senhaHash;this.ativo=true;} @PrePersist void onCreate(){var now=Instant.now();this.criadoEm=now;this.atualizadoEm=now;} @PreUpdate void onUpdate(){this.atualizadoEm=Instant.now();} public Long getId(){return id;} public String getNome(){return nome;} public String getEmail(){return email;} public String getSenhaHash(){return senhaHash;} public boolean isAtivo(){return ativo;} public void alterarSenhaHash(String senhaHash){this.senhaHash=senhaHash;} }
